/**
 * The VierApparatus vector pack: the SVG files generated by scripts/vier-pack/build.mjs, bundled with the app.
 * They are installed into the asset library (folder "VierAsset") on request, as vector assets with no background.
 */
const files = import.meta.glob('../../assets-pack/VierAsset/*.svg', { query: '?raw', import: 'default', eager: true }) as Record<string, string>;

export const VIER_PACK_FOLDER = 'VierAsset';

/** Each file of the pack: the asset name (the file name without .svg) and its SVG text. */
export const vierPack: { name: string; svg: string }[] = Object.entries(files)
  .map(([path, svg]) => ({ name: path.split('/').pop()!.replace(/\.svg$/i, ''), svg }))
  .sort((a, b) => a.name.localeCompare(b.name));
